local _, ns = ...
local Translate = ns.Lore.Translate

Translate("ptBR", "humans", {
	title = "Humanos",
	sections = {
		{
			title = "Resumo",
			text = [=[Os humanos são o mais numeroso dos povos jovens dos {link:eastern-kingdoms}Reinos do Leste{/link}. Vivem pouco ao lado de elfos e anões, mas são inquietos, teimosos e rápidos em aprender. De suas linhagens surgiram os grandes reinos do norte e do sul, e de suas fileiras vieram os paladinos da {link:holy-light}Luz Sagrada{/link} e os magos de {link:dalaran}Dalaran{/link}. Sofreram mais que qualquer outro povo nas guerras contra os orcs e os mortos-vivos, e ainda não se quebraram.]=],
		},
		{
			title = "Origens",
			text = [=[Em tempos antigos, os humanos viviam como tribos dispersas no norte, cada uma desconfiada das demais. Só a tribo {link:arathi-highlands}Arathi{/link} viu que o império {link:trolls}troll{/link} dos Amani as destruiria uma a uma. Seu senhor da guerra, {link:thoradin}Thoradin{/link}, uniu as tribos pela força e pela persuasão, e sobre essa união fundou a nação de {link:arathor}Arathor{/link} e sua cidade-fortaleza de {link:stromgarde-keep}Strom{/link}. Quando os Amani atacaram os {link:high-elves}altos elfos{/link} de {link:quel-thalas}Quel'Thalas{/link}, Arathor atendeu ao chamado dos elfos. Os elfos ensinaram a cem humanos os caminhos da {link:arcane-magic}magia arcana{/link}, e juntos os dois povos quebraram os Amani nas {link:troll-wars}Guerras Trolls{/link}.

Na longa paz que se seguiu, a unidade de Arathor se desfez. Seu povo se espalhou pela terra e fundou novos reinos: {link:lordaeron}Lordaeron{/link} no norte, {link:gilneas}Gilneas{/link} e {link:kul-tiras}Kul Tiraz{/link} nas costas do oeste, {link:alterac-mountains}Alterac{/link} e Stromgarde nas montanhas, {link:city-of-dalaran}a cidade dos magos{/link} em {link:dalaran}Dalaran{/link} e, no extremo sul, o reino de {link:azeroth}Azeroth{/link}, que os homens hoje chamam de {link:kingdom-of-stormwind}Reino de Ventobravo{/link}.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os humanos são um povo de reis e de lavradores. Seus nobres mantêm casas antigas e rixas mais antigas ainda, e seu povo comum trabalha a terra sem pensar muito em nenhuma das duas. A igreja da {link:holy-light}Luz Sagrada{/link} une muitos deles, e seus sacerdotes estão em todas as aldeias. Os humanos prezam juramentos, coragem e dever, embora nem sempre os cumpram. Seu maior dom é reconstruir. O que quer que seja queimado, eles erguem de novo.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os reinos humanos são sombras de sua antiga glória. O {link:scourge}Flagelo{/link} domina as ruínas de {link:lordaeron}Lordaeron{/link}, e a {link:scarlet-crusade}Cruzada Escarlate{/link} trava sua própria guerra impiedosa no norte. {link:gilneas}Gilneas{/link} se fechou atrás de sua grande muralha. {link:alterac-mountains}Alterac{/link} está em ruínas, e {link:stromgarde-keep}Stromgarde{/link} se agarra ao que resta do {link:arathi-highlands}Planalto Arathi{/link}. No sul, {link:stormwind-city}Ventobravo{/link} foi reconstruída, mas o Rei {link:varian-wrynn}Varian Wrynn{/link} desapareceu, e o Grão-lorde {link:bolvar-fordragon}Bolvar Fordragon{/link} governa em seu nome. Do outro lado do mar, Lady {link:jaina-proudmoore}Jaina Proudmoore{/link} mantém a fortaleza insular da {link:theramore-isle}Ilha Theramore{/link}, onde os humanos sustentam uma paz inquieta com a {link:horde}Horda{/link}. A humanidade continua sendo o coração da {link:alliance}Aliança{/link}, e é um coração que sangra.]=],
		},
	},
})

Translate("ptBR", "dwarves", {
	title = "Anões",
	aliases = { "anão" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os anões são um povo robusto e resistente das montanhas de Khaz Modan. São mineiros, ferreiros, cervejeiros e guerreiros, e estão entre os melhores artesãos do mundo. Sua grande cidade de {link:ironforge}Altaforja{/link} é escavada no coração de uma montanha. Lutam ao lado da humanidade desde a {link:second-war}Segunda Guerra{/link}, e continuam sendo um dos pilares da {link:alliance}Aliança{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Por eras os anões viveram sob as montanhas, e suas próprias lendas diziam que eles tinham sido moldados da pedra. Nos salões de {link:uldaman}Uldaman{/link}, estudiosos da {link:explorers-league}Liga dos Exploradores{/link} encontraram registros dos Titãs que parecem confirmar isso: falam dos terranos, seres de rocha viva feitos pelos Titãs para moldar os lugares profundos do mundo. Muitos anões acreditam agora que seu povo descende deles.

Os anões estiveram por muito tempo unidos sob um único grande rei em {link:ironforge}Altaforja{/link}. Quando esse rei morreu, três grandes clãs guerrearam por seu trono. {link:nessa-shadowsong}Nessa{/link} Guerra dos Três Martelos, o clã Barbabronze manteve Altaforja. O clã Martelo Feroz foi expulso para o norte e, com o tempo, fez seu lar nas {link:the-hinterlands}Terras Agrestes{/link}. O {link:dark-iron-dwarves}clã Ferro Negro{/link} foi lançado ao sul. Lá, seu rei-feiticeiro, {link:ruins-of-thaurissan}Thaurissan{/link}, buscou um poder para vingar sua derrota, e invocou {red:ragnaros}Ragnaros{/red}, o Senhor do Fogo. O fogo dessa invocação partiu a terra e prendeu os Ferro Negro ao serviço do Senhor do Fogo.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os anões são orgulhosos, leais e lentos para perdoar. Amam uma boa cerveja, uma canção barulhenta e um machado bem feito. Respeitam mais os feitos que as palavras e são conhecidos por sua longa memória. Seus armeiros são famosos por todos os {link:eastern-kingdoms}Reinos do Leste{/link}, e seus rifles e canhões já defenderam muitas muralhas. Os Martelo Feroz são mais selvagens que seus parentes e montam grifos na batalha, enquanto os Barbabronze preferem a forja e o rifle.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[O Rei {link:magni-bronzebeard}Magni Bronzebeard{/link} governa em {link:ironforge}Altaforja{/link}. Seu irmão {link:brann-bronzebeard}Brann Bronzebeard{/link} lidera a {link:explorers-league}Liga dos Exploradores{/link}, cujos escavadores reviram ruínas por todo o mundo em busca do verdadeiro passado dos anões. Altaforja abriu seus portões aos {link:gnomes}gnomos{/link} que perderam sua cidade para os {link:troggs}troggs{/link}, e {link:tinker-town}Tinker Town{/link} ressoa agora com o trabalho dos gnomos. Os {link:dark-iron-dwarves}anões Ferro Negro{/link} continuam sendo os inimigos mais amargos de seus primos, e nas profundezas da {link:blackrock-mountain}Montanha Rocha Negra{/link} trabalham a serviço do Senhor do Fogo. Os Martelo Feroz seguem seus próprios conselhos nas {link:the-hinterlands}Terras Agrestes{/link}, aliados de Altaforja, mas nunca seus súditos.]=],
		},
	},
})

Translate("ptBR", "gnomes", {
	title = "Gnomos",
	aliases = { "gnomo" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os gnomos são um povo pequeno, engenhoso e infinitamente curioso. São os maiores inventores e engenheiros do mundo, e veem um problema a resolver em tudo o que encontram. Por gerações viveram na maravilhosa cidade de {link:gnomeregan}Gnomeregan{/link}, nas montanhas de {link:dun-morogh}Dun Morogh{/link}. Essa cidade está perdida para eles agora, e vivem como hóspedes dos {link:dwarves}anões{/link} em {link:ironforge}Altaforja{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Os gnomos há muito são vizinhos e amigos dos anões de Khaz Modan. De seus primeiros dias, as histórias de {link:azeroth}Azeroth{/link} dizem pouco. O certo é que construíram {link:gnomeregan}Gnomeregan{/link} com as próprias mãos e a encheram de maravilhas: grandes motores, servos de engrenagem e aparelhos que nenhum outro povo poderia ter imaginado. Na {link:second-war}Segunda Guerra{/link}, juntaram-se à {link:alliance}Aliança{/link} ao lado dos anões. Enviaram poucos soldados, pois não são um povo numeroso, mas deram à Aliança máquinas voadoras, submarinos e armas de sua própria invenção.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os gnomos são brilhantes, rápidos e alegres mesmo nas horas mais sombrias. Também se distraem com facilidade, e suas invenções nem sempre fazem o que seus criadores pretendiam. Prezam a engenhosidade acima da força, e têm seus mestres engenheiros na mais alta honra. Seu líder tem o título de Grão-Engenhoqueiro. Muitos gnomos também estudam {link:arcane-magic}magia arcana{/link}, e alguns se voltam para artes mais sombrias que outros acham melhor deixar em paz.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Depois da {link:third-war}Terceira Guerra{/link}, os {link:troggs}troggs{/link} subiram de sob a terra e invadiram {link:gnomeregan}Gnomeregan{/link}. A cidade não pôde ser mantida. O Grão-Engenhoqueiro {link:gelbin-mekkatorque}Gelbin Mekkatorque{/link} fez uma escolha desesperada e liberou uma arma tóxica para expulsar os invasores. Ela matou muitos troggs, mas matou também um grande número de gnomos, e deixou a cidade envenenada. Os sobreviventes fugiram para {link:ironforge}Altaforja{/link}. Sussurra-se agora que a queda não foi um acidente: o próprio conselheiro do Grão-Engenhoqueiro, {link:mekgineer-thermaplugg}Sicco Thermaplugg{/link}, teria traído seu povo, e agora governa a cidade arruinada como seu senhor louco. Os gnomos sonham com o dia em que retomarão seu lar. Até lá, inventam em Altaforja e servem à {link:alliance}Aliança{/link} com o mesmo zelo de sempre.]=],
		},
	},
})

Translate("ptBR", "night-elves", {
	title = "Elfos Noturnos",
	aliases = { "kaldorei", "kal'dorei", "elfo noturno" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os elfos noturnos, que se chamam de kaldorei ou "filhos das estrelas", são o mais antigo povo civilizado de {link:kalimdor}Kalimdor{/link}. São altos, de pele violeta e longevos, e guardam as florestas do norte há dez mil anos. Suas sacerdotisas servem à deusa da lua, Elune, e seus druidas cuidam do mundo selvagem nos caminhos ensinados pelo semideus {link:cenarius}Cenarius{/link}. Depois da {link:third-war}Terceira Guerra{/link}, juntaram-se à {link:alliance}Aliança{/link} pela primeira vez em sua história.]=],
		},
		{
			title = "Origens",
			text = [=[Os primeiros elfos noturnos foram uma tribo que se estabeleceu nas margens do {link:well-of-eternity}Poço da Eternidade{/link} em tempos antigos. O poder do Poço os transformou e lhes deu vida longa. Em suas margens ergueram um grande império, governado pela {link:queen-azshara}Rainha Azshara{/link} e por sua casta de feiticeiros Bem-nascidos. Os Bem-nascidos se embriagaram do poder do Poço, e por fim sua magia atraiu o olhar da {link:burning-legion}Legião Ardente{/link}. {link:azshara}Azshara{/link} abriu caminho para os demônios, e começou a {link:war-of-the-ancients}Guerra dos Antigos{/link}.

O druida {link:malfurion-stormrage}Malfurion Stormrage{/link}, a sacerdotisa {link:tyrande-whisperwind}Tyrande Whisperwind{/link} e seus aliados rechaçaram a Legião. No fim, o Poço foi destruído, e a {link:great-sundering}Grande Cisão{/link} despedaçou o antigo continente. Os elfos noturnos que sobreviveram deram as costas à magia arcana. No {link:mount-hyjal}Monte Hyjal{/link}, cuidaram de uma nova árvore da vida, {link:nordrassil}Nordrassil{/link}, que lhes concedeu a imortalidade. Os Bem-nascidos que se recusaram a abandonar sua magia foram mandados para o exílio do outro lado do mar.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os elfos noturnos são um povo paciente e vigilante. Suas mulheres serviram por muito tempo como {link:sentinels}Sentinelas{/link}, as guerreiras que guardam as florestas, enquanto seus homens se tornaram druidas que dormiram por longos anos no {link:emerald-dream}Sonho Esmeralda{/link}. Amam os lugares selvagens do mundo e odeiam quem os devasta. Não confiam no arcano, pois ele quase acabou com seu mundo.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Na {link:third-war}Terceira Guerra{/link}, a Legião voltou. Na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, elfos noturnos, humanos e orcs se uniram contra {link:archimonde}Archimonde{/link}, e o poder de {link:nordrassil}Nordrassil{/link} foi gasto para destruí-lo. Com ele, os elfos noturnos perderam a imortalidade. O Arquidruida {link:fandral-staghelm}Fandral Staghelm{/link} e seus druidas ergueram então uma nova Árvore do Mundo, {link:teldrassil}Teldrassil{/link}, ao largo da costa norte, e a cidade de {link:darnassus}Darnassus{/link} cresceu em seus galhos. {link:tyrande-whisperwind}Tyrande{/link} governa ali como Suma Sacerdotisa, enquanto {link:malfurion-stormrage}Malfurion{/link} caminha pelo {link:emerald-dream}Sonho Esmeralda{/link} e não voltou. Os kaldorei enfrentam agora os orcs que derrubam as florestas do {link:ashenvale}Vale Gris{/link}, e a corrupção que se espalha pela {link:felwood}Selva Maleva{/link}.]=],
		},
	},
})

Translate("ptBR", "orcs", {
	title = "Orcs",
	aliases = { "orc" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os orcs são um orgulhoso povo guerreiro do mundo de Draenor. Vieram a {link:azeroth}Azeroth{/link} como conquistadores através do {link:dark-portal}Portal Negro{/link}, e trouxeram fogo e ruína aos reinos humanos. Foram derrotados, aprisionados e quebrados, mas se reergueram. Sob seu Chefe Guerreiro, {link:thrall}Thrall{/link}, atravessaram o mar até {link:kalimdor}Kalimdor{/link} e construíram uma nova pátria em {link:durotar}Durotar{/link}. São o coração da {link:horde}Horda{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Em Draenor, os orcs viviam em muitos clãs. Eram caçadores e guerreiros, guiados por xamãs que falavam com os espíritos dos {link:elements}elementos{/link}. O senhor demoníaco {link:kil-jaeden}Kil'jaeden{/link} decidiu fazer deles uma arma da {link:burning-legion}Legião Ardente{/link}. Enganou o velho xamã {link:ner-zhul}Ner'zhul{/link} e, depois dele, o aprendiz de Ner'zhul, {link:gul-dan}Gul'dan{/link}. Gul'dan ensinou aos clãs as artes dos bruxos, e os elementos deram as costas aos orcs. Por fim, os chefes beberam o sangue do demônio {link:mannoroth}Mannoroth{/link}, e uma sede de sangue tomou conta de todo o povo.

Através do {link:dark-portal}Portal Negro{/link}, a {link:horde}Horda{/link} caiu sobre o reino de {link:azeroth}Azeroth{/link}. Venceu a {link:first-war}Primeira Guerra{/link} e incendiou {link:stormwind-city}Ventobravo{/link}. Sob {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, quase venceu também a {link:second-war}Segunda Guerra{/link}, mas foi traída por dentro e derrotada. Os orcs sobreviventes foram levados para campos de internamento, onde uma estranha letargia caiu sobre eles.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os orcs honram a força, a coragem e a lealdade ao clã. Respeitam o xamã que fala pelos espíritos e o guerreiro que se mantém firme na batalha. Seus nomes são orgulhosos, e sua memória também: cada clã guarda suas próprias lendas e seus próprios rancores. Desde o fim da maldição do demônio, muitos orcs voltaram aos antigos caminhos do xamã e buscam o equilíbrio com os elementos.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[O jovem orc {link:thrall}Thrall{/link}, criado como escravo numa fortaleza humana, escapou de seus senhores e libertou seu povo dos campos. Ao chamado de um profeta, levou-o para o oeste, até {link:kalimdor}Kalimdor{/link}. Ali, na {link:third-war}Terceira Guerra{/link}, {link:grom-hellscream}Grom Hellscream{/link} matou {link:mannoroth}Mannoroth{/link} e libertou os orcs do sangue do demônio. Thrall deu à sua nova terra o nome de {link:durotar}Durotar{/link}, em honra de seu pai, Durotan, e à sua capital o nome de {link:orgrimmar}Orgrimmar{/link}, em honra de Doomhammer. Os orcs mantêm agora uma paz inquieta com a {link:theramore-isle}Ilha Theramore{/link}. Mas nem todos os orcs deram as costas à antiga escuridão. O culto da {link:burning-blade}Lâmina Ardente{/link} sussurra nas cavernas de Durotar, e nos {link:eastern-kingdoms}Reinos do Leste{/link} o {link:blackrock-clan}clã Rocha Negra{/link} ainda serve aos dragões negros na {link:blackrock-mountain}Montanha Rocha Negra{/link}.]=],
		},
	},
})

Translate("ptBR", "trolls", {
	title = "Trolls",
	sections = {
		{
			title = "Resumo",
			text = [=[Os trolls estão entre os povos mais antigos de {link:azeroth}Azeroth{/link}. São altos, dentuços e ferozes, e seus corpos curam feridas que matariam qualquer outra criatura. Muito antes de os elfos noturnos erguerem seu império, os trolls governavam grandes reinos próprios. Esses impérios caíram, e as tribos que restam são amargas, divididas e perigosas. Uma delas, a tribo {link:darkspear-trolls}Lançanegra{/link}, está agora com a {link:horde}Horda{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[O reino troll mais antigo foi o dos Zandalari, cuja tribo vivia longe, ao sul. Deles vieram os dois grandes impérios dos tempos antigos: os Amani, nas florestas do norte, e os Gurubashi, nas selvas do sul. Adoravam espíritos poderosos chamados loa, e guerrearam contra os primeiros elfos noturnos e perderam. A {link:great-sundering}Grande Cisão{/link} despedaçou suas terras.

Os Amani nunca perdoaram os altos elfos que se estabeleceram em suas florestas. Nas {link:troll-wars}Guerras Trolls{/link}, estiveram perto de destruir {link:quel-thalas}Quel'Thalas{/link}, até que os humanos de {link:arathor}Arathor{/link} se juntaram aos elfos e os quebraram. No sul, os Gurubashi caíram em guerra civil quando os sacerdotes dos Atal'ai invocaram {link:hakkar}Hakkar{/link}, o deus do sangue. As tribos derrubaram o deus e expulsaram os Atal'ai para os pântanos, onde eles construíram o templo de {link:temple-of-atal-hakkar}Atal'Hakkar{/link}. Seu império nunca se recuperou.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os trolls são caçadores e saqueadores. Seus sacerdotes praticam o vodu e falam com os loa, e seus curandeiros preparam poções e feitiços que outros povos temem. Muitas tribos mantêm costumes cruéis, e diz-se que algumas comem seus inimigos. Orgulham-se de seu passado antigo e se ressentem dos povos mais jovens que tomaram suas terras. Poucos trolls confiam em estranhos, e menos ainda recebem confiança em troca.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[A {link:darkspear-trolls}tribo Lançanegra{/link} foi expulsa de seu lar nas selvas e encontrou refúgio nos mares do sul. Ali {link:thrall}Thrall{/link} os salvou dos humanos e da bruxa do mar, e seu líder Sen'jin deu a vida para que seu povo pudesse seguir os orcs. Hoje os Lançanegra servem à {link:horde}Horda{/link} sob {link:vol-jin}Vol'jin{/link}. Estabeleceram-se nas {link:echo-isles}Ilhas do Eco{/link}, ao largo de {link:durotar}Durotar{/link}, mas um curandeiro chamado {link:zalazane}Zalazane{/link} tomou as ilhas com magia sombria, e a tribo se recolheu à {link:sen-jin-village}Aldeia Sen'jin{/link}, no continente. Em outros lugares, as tribos trolls continuam inimigas de todos: os Amani nas florestas do norte, os {link:witherbark-trolls}Cascasseca{/link} e os Ramatorpe nas {link:the-hinterlands}Terras Agrestes{/link}, as tribos Gurubashi da {link:stranglethorn-vale}Selva do Espinhaço{/link}, os {link:sandfury-trolls}Sandfury{/link} de {link:tanaris}Tanaris{/link} e os {link:frostmane-trolls}Jubafria{/link} de {link:dun-morogh}Dun Morogh{/link}.]=],
		},
	},
})

Translate("ptBR", "tauren", {
	title = "Taurens",
	aliases = { "tauren", "shu'halo" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os taurens são um povo de grande estatura e sabedoria serena que percorre as planícies de {link:kalimdor}Kalimdor{/link}. São enormes e parecidos com touros, e podem ser terríveis na batalha, mas preferem viver em paz com a terra. Reverenciam a Mãe Terra acima de todas as coisas. Sob seu grande chefe, {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, estabeleceram-se nas pradarias de {link:mulgore}Mulgore{/link} e se juntaram à {link:horde}Horda{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Os taurens, que se chamam de shu'halo, estão entre os povos mais antigos de {link:kalimdor}Kalimdor{/link}. Por eras vagaram pelas planícies como nômades, seguindo as grandes manadas e a passagem das estações. Dizem que a Mãe Terra lhes deu a terra, e que o sol e a lua são seus olhos, a que chamam An'she e Mu'sha. As tribos viviam separadas, cada uma com seus próprios chefes e seus próprios totens.

Essa vida quase foi destruída pelos {link:centaurs}centauros{/link}. Os cruéis homens-cavalo das planícies caçaram as tribos dispersas por gerações e as expulsaram de suas terras ancestrais. {link:cairne-bloodhoof}Cairne Bloodhoof{/link} dedicou-se a unir as tribos contra eles. Quando os orcs vieram a Kalimdor, Cairne conheceu o jovem {link:thrall}Thrall{/link}, e os dois povos se reconheceram como parentes de espírito. Com a ajuda dos orcs, os taurens quebraram o domínio dos centauros sobre {link:mulgore}Mulgore{/link} e a reivindicaram como sua pátria.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os taurens vivem perto da terra. Caçam com respeito e tomam apenas o que precisam. Seus xamãs falam com os espíritos dos {link:elements}elementos{/link} e de seus ancestrais, e alguns taurens aprenderam os caminhos do druida, treinados pelos elfos noturnos do {link:cenarion-circle}Círculo Cenariano{/link}. São pacientes, lentos para se irar e honestos até demais. Seus totens registram as linhagens e os feitos de suas tribos.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os taurens construíram sua capital, {link:thunder-bluff}Penhasco do Trovão{/link}, sobre altas mesetas acima de {link:mulgore}Mulgore{/link}, alcançadas por grandes elevadores. {link:cairne-bloodhoof}Cairne{/link} governa ali como Chefe Supremo, respeitado até por quem teme a {link:horde}Horda{/link}. Nem todas as tribos compartilham sua visão. A {link:grimtotem-clan}tribo Temível Totem{/link}, liderada pela velha anciã {link:magatha-grimtotem}Magatha{/link}, tem suas próprias ambições, e muitos em Penhasco do Trovão pouco confiam nela. Em torno de Mulgore, os taurens ainda enfrentam inimigos: os javatuscos da tribo {link:bristleback-quilboar}Costagulha{/link}, as harpias das serras e os centauros dos {link:the-barrens}Sertões{/link}. Os taurens honram sua dívida com os orcs, e estão entre os membros mais firmes da Horda.]=],
		},
	},
})

Translate("ptBR", "forsaken", {
	title = "Renegados",
	sections = {
		{
			title = "Resumo",
			text = [=[Os Renegados são mortos-vivos que se libertaram da vontade do Lich Rei. Outrora foram o povo de {link:lordaeron}Lordaeron{/link}. Morreram na praga, ergueram-se como escravos do {link:scourge}Flagelo{/link} e então, numa única hora de fraqueza no domínio de seu senhor, despertaram de novo para as próprias mentes. Seguem {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, a Rainha Banshee, e fizeram um reino sombrio sob as ruínas de sua antiga capital. Por razões próprias, juntaram-se à {link:horde}Horda{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Na {link:third-war}Terceira Guerra{/link}, a praga do {link:cult-of-the-damned}Culto dos Malditos{/link} varreu {link:lordaeron}Lordaeron{/link}, e o Príncipe {link:arthas-menethil}Arthas Menethil{/link} assassinou seu pai, {link:terenas-menethil}Terenas Menethil{/link}, e entregou o reino ao {link:scourge}Flagelo{/link}. Milhares dos que morreram se ergueram de novo a serviço do Lich Rei. Por um tempo, não tiveram vontade alguma.

Então o poder do Lich Rei vacilou, e muitos dos mortos-vivos de Lordaeron descobriram que podiam pensar por si mesmos outra vez. {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, a general-patrulheira caída de {link:quel-thalas}Quel'Thalas{/link}, fora erguida como banshee pelo próprio Arthas. Ela se libertou com eles. Voltou-se contra os senhores do medo que buscavam governar o reino arruinado, e prendeu um deles, {link:varimathras}Varimathras{/link}, a seu serviço. Chamou seu povo de Renegados, e o levou a tomar como suas as ruínas da capital de Lordaeron.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os Renegados lembram suas vidas, mas não podem voltar a elas. Seus amigos e parentes os temem e os odeiam, e muitos deles aprenderam a odiar em troca. São sombrios, amargos e práticos. Seus estudiosos buscam toda arte da alquimia e da necromancia sem vergonha, e seus sacerdotes deram as costas à {link:holy-light}Luz Sagrada{/link} e se voltaram para a sombra. Entre os vivos, são mais tolerados do que confiáveis.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Sob a cidade destroçada de {link:lordaeron}Lordaeron{/link}, os Renegados ergueram a {link:undercity}Cidade Baixa{/link}, um labirinto de salões e esgotos construído nas antigas criptas reais. Dali, {link:sylvanas-windrunner}Sylvanas{/link} governa as {link:tirisfal-glades}Clareiras de Tirisfal{/link} e trava guerra em duas frentes: contra o {link:scourge}Flagelo{/link}, que ainda domina as terras pestilentas, e contra a {link:scarlet-crusade}Cruzada Escarlate{/link}, que queima todo morto-vivo que encontra. Sua aliança com a {link:horde}Horda{/link} é de necessidade. Os orcs e os taurens os acham estranhos e inquietantes. Os Renegados, por sua vez, pouco dizem de seus verdadeiros objetivos, e os químicos da {link:royal-apothecary-society}Real Sociedade de Boticários{/link} trabalham em segredo numa nova praga.]=],
		},
	},
})

Translate("ptBR", "skyborne", {
	title = "Skyborne",
	aliases = { "shen'dorei" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Skyborne, que se chamam de shen'dorei ou "povo oculto", são elfos que viveram por milhares de anos além do próprio mundo. Seu lar é {link:zephras-isle}Zephras Isle{/link}, uma ilha que flutua em {link:skywall}Skywall{/link}, o plano elemental do ar. Compartilham o sangue dos Bem-nascidos, e são primos dos {link:high-elves}altos elfos{/link} de {link:quel-thalas}Quel'Thalas{/link}. Agora seu reino celeste está desmoronando, e uma nova geração de Skyborne desceu a {link:azeroth}Azeroth{/link} em busca de respostas.]=],
		},
		{
			title = "Origens",
			text = [=[Os Skyborne remontam sua linhagem aos Bem-nascidos de Eldre'Thalas, a cidade em {link:feralas}Feralas{/link} hoje chamada {red:dire-maul}Gládio Cruel{/red}. Depois da {link:war-of-the-ancients}Guerra dos Antigos{/link}, o Príncipe {red:tortheldrin}Tortheldrin{/red} buscou sustentar a cidade com poderes cada vez mais perigosos. Parte de seu povo tinha visto o que essa fome de poder fizera ao mundo, e se levantou contra ele. Frustraram seus planos, mas sua rebelião foi esmagada, e eles fugiram através do mar com a frota do príncipe em seu encalço.

Muito a oeste, chegaram a uma terra governada por antigos espíritos dos {link:elements}elementos{/link}. Ali fizeram um pacto com os {link:vanishing-of-the-wind-spirits}espíritos do vento{/link}. Os espíritos arrancaram uma grande parte daquela terra para o céu e a levaram para fora do mundo, e a ancoraram em {link:skywall}Skywall{/link}. Escondidos de seus perseguidores, os exilados construíram uma pequena e luminosa civilização entre as nuvens.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[As longas eras em {link:skywall}Skywall{/link} mudaram os shen'dorei. Tornaram-se mais leves e mais velozes que seus ancestrais, e a magia do ar marcou seus cabelos, seus olhos e sua pele. Viveram ao lado dos {link:vanishing-of-the-wind-spirits}espíritos do vento{/link} como alunos e amigos. Alguns entre eles receberam dos espíritos o dom da visão celeste, o poder de ver através do plano elemental. Os espíritos raramente falavam de {link:al-akir}Al'Akir{/link}, o Senhor dos Ventos, mestre de Skywall, e entre os Skyborne seu nome tornou-se coisa de pavor e silêncio.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Sem aviso, os {link:vanishing-of-the-wind-spirits}espíritos do vento{/link} desapareceram. Os antigos pilares que mantêm {link:zephras-isle}Zephras Isle{/link} unida começaram a falhar, partes da ilha caíram em ruínas, e suas comunidades estão isoladas umas das outras. Os Skyborne estão divididos sobre o que fazer.

• {b}Os {link:windshapers}Windshapers{/link}.{/b} Descendentes dos primeiros shen'dorei a receber a visão celeste, são os guias espirituais da ilha. Buscam descobrir o que aconteceu aos espíritos do vento e restaurá-los. Juntaram-se à {link:horde}Horda{/link}.
• {b}A {link:high-order}High Order{/link}.{/b} Descendentes dos magísteres Bem-nascidos que fugiram de Eldre'Thalas, acreditam que os Skyborne confiaram demais em seus patronos. Buscam o saber arcano que seus ancestrais perderam, para que seu povo possa andar com as próprias pernas. Juntaram-se à {link:alliance}Aliança{/link}.
• {b}Os {link:al-aketh}Al'Aketh{/link}.{/b} Um culto que se afastou do resto dos shen'dorei para servir a {link:al-akir}Al'Akir{/link}. Encorajados pela ausência dos espíritos, espalharam o medo e tomaram grande parte da ilha.]=],
		},
	},
})

Translate("ptBR", "high-elves", {
	title = "Altos Elfos",
	aliases = { "quel'dorei", "alto elfo" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os altos elfos, ou quel'dorei, são os filhos dos Bem-nascidos exilados que atravessaram o mar depois da {link:great-sundering}Grande Cisão{/link}. Nas florestas do norte de {link:lordaeron}Lordaeron{/link} construíram o reino de {link:quel-thalas}Quel'Thalas{/link} e sua capital resplandecente, Luaprata. Por milhares de anos foram os mestres da {link:arcane-magic}magia arcana{/link} nos {link:eastern-kingdoms}Reinos do Leste{/link}. Na {link:third-war}Terceira Guerra{/link}, seu reino foi quase destruído.]=],
		},
		{
			title = "Origens",
			text = [=[Depois da {link:great-sundering}Cisão{/link}, os elfos noturnos proibiram o uso da magia arcana. Os Bem-nascidos que não quiseram obedecer, liderados por {red:dath-remar-sunstrider}Dath'Remar Sunstrider{/red}, foram exilados. Navegaram para o leste e, depois de longa errância, chegaram às florestas do norte, onde lutaram contra os {link:trolls}trolls{/link} Amani por seu novo lar. Ali criaram a Nascente do Sol, uma fonte de poder arcano que sustentava seu povo. Quando os Amani se levantaram contra eles, aliaram-se aos {link:humans}humanos{/link} de {link:arathor}Arathor{/link} e lhes ensinaram magia, e juntos venceram as {link:troll-wars}Guerras Trolls{/link}.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os altos elfos são graciosos, orgulhosos e eruditos. Amam a beleza e a magia, e muitos deles olham com desdém para os povos mais jovens. Seus patrulheiros são os melhores arqueiros do norte. Seu vínculo com a Nascente do Sol era tão profundo que passaram a depender de seu poder.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Na {link:third-war}Terceira Guerra{/link}, {link:arthas-menethil}Arthas Menethil{/link} conduziu o {link:scourge}Flagelo{/link} a {link:quel-thalas}Quel'Thalas{/link}. Matou o Rei Anasterian Sunstrider e usou a Nascente do Sol para erguer o lich {link:kel-thuzad}Kel'Thuzad{/link}. A General-patrulheira {link:sylvanas-windrunner}Sylvanas Windrunner{/link} caiu na defesa de sua pátria. Os poucos que sobreviveram continuam dispersos: alguns ainda mantêm o que resta de Quel'Thalas, alguns servem à {link:alliance}Aliança{/link} e ao {link:kirin-tor}Kirin Tor{/link}, e um pequeno bando mantém o pavilhão de caça de {link:quel-danil-lodge}Quel'Danil{/link} nas {link:the-hinterlands}Terras Agrestes{/link}. O Príncipe Kael'thas, herdeiro dos Sunstrider, reuniu muitos dos sobreviventes e os renomeou sin'dorei, os elfos sangrentos, em memória dos caídos. O que foi dele desde então, nenhuma crônica destas terras sabe dizer.]=],
		},
	},
})

Translate("ptBR", "kobolds", {
	title = "Kobolds",
	aliases = { "kobold" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os kobolds são pequenas criaturas parecidas com ratos que habitam minas e cavernas por toda {link:azeroth}Azeroth{/link}. São covardes, gananciosos e pouco espertos, mas existem em enorme número. Onde quer que uma velha mina fique sem guarda, os kobolds se instalam. Cada um usa uma vela na cabeça para iluminar os túneis, e cada um preferiria morrer a abrir mão dela.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra de onde os kobolds vieram. Alguns escavadores da {link:explorers-league}Liga dos Exploradores{/link} acreditam que eles surgiram dos {link:troggs}troggs{/link} dos lugares profundos. Quaisquer que tenham sido suas origens, já eram um incômodo para os primeiros colonos de {link:tirisfal-glades}Tirisfal{/link}, e desde então atormentam os mineiros.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os kobolds adoram os túneis escuros, mas temem a escuridão verdadeira, e suas velas são as coisas mais preciosas que possuem. Roubar uma é o pior dos crimes, e o ladrão vai ouvir falar disso. Cavam sem parar e acumulam tudo o que brilha. Seus geomantes praticam uma magia rústica de fogo e pedra. A maioria se contenta em lutar só quando encurralada, mas em enxame podem sobrepujar um mineiro descuidado.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os kobolds infestam as minas da {link:elwynn-forest}Floresta de Elwynn{/link} e do {link:westfall}Cerro Oeste{/link}, onde cavam ouro que não fica em suas mãos. Diz-se que são conduzidos pelos {link:riverpaw-gnolls}gnolls Pata Molhada{/link}, que por sua vez negociam com a {link:defias-brotherhood}Irmandade Défias{/link}. Os {link:tunnel-rat-kobolds}Tunnel Rats{/link} atormentam os anões de {link:loch-modan}Loch Modan{/link}, e em {link:kalimdor}Kalimdor{/link} kobolds cavam para a {link:venture-company}Empreendimentos S.A.{/link} na {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link}.]=],
		},
	},
})

Translate("ptBR", "gnolls", {
	title = "Gnolls",
	aliases = { "gnoll" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os gnolls são criaturas parecidas com hienas que percorrem os lugares selvagens dos {link:eastern-kingdoms}Reinos do Leste{/link} e de {link:kalimdor}Kalimdor{/link}. São brutos, briguentos e famintos, e valorizam a força acima de tudo. Vivem em bandos e clãs, cada um governado pelo mais forte entre eles, e saqueiam as fazendas e estradas de outros povos em busca de comida e pilhagem.]=],
		},
		{
			title = "Origens",
			text = [=[Os gnolls são um povo antigo de {link:azeroth}Azeroth{/link}, e nenhuma crônica registra seu início. Estavam entre os perigos enfrentados pelos primeiros colonos humanos no norte. O reino de {link:stormwind-city}Ventobravo{/link} lembra um tempo mais sombrio, quando um senhor de bando dos gnolls de {link:redridge-mountains}Cristarrubra{/link} chamado Garfang reuniu os clãs numa grande hoste e atacou as fazendas do reino. O Rei Barathen Wrynn cavalgou contra ele e o matou, e os bandos se despedaçaram na disputa que se seguiu.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os gnolls preferem deixar que outros façam o seu trabalho. Seus líderes empurram os fracos à frente, e eles servem de bom grado a qualquer senhor mais forte que lhes prometa comida e pilhagem. Seus místicos praticam um xamanismo rústico. São astutos o bastante para armar ciladas e emboscadas, e cruéis o bastante para gostar disso.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os gnolls perturbam quase todas as fronteiras das terras humanas. Os {link:riverpaw-gnolls}Pata Molhada{/link} saqueiam a {link:elwynn-forest}Floresta de Elwynn{/link} e o {link:westfall}Cerro Oeste{/link}. O bando Cristarrubra e os {link:shadowhide-gnolls}Umbrapele{/link} rondam as {link:redridge-mountains}Montanhas Cristarrubra{/link}, estes últimos escravizados pelo bruxo {link:morganth}Morganth{/link}. Os Pelemusgo assombram o {link:wetlands}Pantanal{/link}, os Putricouro desenterram os mortos das {link:tirisfal-glades}Clareiras de Tirisfal{/link} para o {link:scourge}Flagelo{/link}, e outros clãs percorrem as colinas de {link:hillsbrad-foothills}Eira dos Montes{/link} e as florestas de {link:feralas}Feralas{/link}.]=],
		},
	},
})

Translate("ptBR", "riverpaw-gnolls", {
	title = "Gnolls Pata Molhada",
	aliases = { "gnolls Pata Molhada", "Pata Molhada" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Pata Molhada são o clã de gnolls que atormenta as terras do sul do {link:kingdom-of-stormwind}Reino de Ventobravo{/link}. Percorrem a fronteira da {link:elwynn-forest}Floresta de Elwynn{/link}, os campos do {link:westfall}Cerro Oeste{/link} e seguem em direção às {link:redridge-mountains}Montanhas Cristarrubra{/link}. Saqueiam fazendas, emboscam viajantes e combatem os poucos soldados que o reino pode dispensar. O mais temido deles é o grande {link:gnolls}gnoll{/link} {link:hogger}Hogger{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[Os Pata Molhada ficaram mais ousados desde que o exército do reino foi enviado para longe. Saem da Boca da Mata para atacar as fazendas do sul de {link:elwynn-forest}Elwynn{/link}, e a {link:westbrook-garrison}Guarnição da Ribeira d'Oeste{/link} paga uma recompensa por cada pata que seus voluntários trazem de volta. No {link:westfall}Cerro Oeste{/link} seus acampamentos são ainda maiores. A Milícia do Povo encontrou sinais de que os Pata Molhada não lutam só por si mesmos: conduzem escravos {link:kobolds}kobolds{/link} nas minas, e negociam com a {link:defias-brotherhood}Irmandade Défias{/link}. Muitos em {link:stormwind-city}Ventobravo{/link} se perguntam quem os arma, e quem lhes dá sua astúcia incomum.]=],
		},
	},
})

Translate("ptBR", "murlocs", {
	title = "Murlocs",
	aliases = { "murloc" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os murlocs são pequenas criaturas parecidas com peixes que vivem ao longo das costas, lagos e rios de {link:azeroth}Azeroth{/link}. Andam sobre duas pernas, falam uma língua gorgolejante que nenhum outro povo entende, e atacam em enxames repentinos. Todo pescador dos {link:eastern-kingdoms}Reinos do Leste{/link} e de {link:kalimdor}Kalimdor{/link} tem uma história sobre os murlocs.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra de onde vieram os murlocs. Assombram as margens do mundo desde que algum povo guarda registros, e parecem não se importar nem um pouco com as guerras dos habitantes da terra.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os murlocs vivem em tribos, em aldeias de cabanas construídas à beira d'água. Caçam peixes e tudo o mais que se aproxime de suas margens. Seus oráculos e caçadores das marés empunham uma magia simples de água e tempestade. Raramente são perigosos sozinhos, mas raramente vêm sozinhos. Quando um murloc é atacado, outros surgem das águas rasas com um grito terrível.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os murlocs ficaram ousados à medida que os reinos enfraquecem. Saqueiam as margens dos lagos da {link:elwynn-forest}Floresta de Elwynn{/link} e a costa do {link:westfall}Cerro Oeste{/link}. A tribo Peixeazul assombra os charcos do {link:wetlands}Pantanal{/link}, e a tribo Greymist as praias da {link:darkshore}Costa Negra{/link}. Em todas as costas, da {link:stranglethorn-vale}Selva do Espinhaço{/link} a {link:durotar}Durotar{/link}, suas cabanas se erguem à beira d'água.]=],
		},
	},
})

Translate("ptBR", "quilboar", {
	title = "Javatuscos",
	aliases = { "javatusco" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os javatuscos são um povo selvagem de homens-javali que habita o sul dos {link:the-barrens}Sertões{/link} e as terras ao redor. São cobertos de cerdas e espinhos, e fazem seus lares entre grandes emaranhados de vinhas espinhosas. São hostis a quase todos os outros povos, e há muito estão em guerra com os {link:tauren}taurens{/link} e os orcs.]=],
		},
		{
			title = "Origens",
			text = [=[Os javatuscos afirmam ser filhos de Agamaggan, o grande semideus javali. Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, Agamaggan lutou contra a {link:burning-legion}Legião Ardente{/link} e foi morto. Onde seu sangue caiu, imensas vinhas espinhosas brotaram da terra. Esses espinhos se tornaram o Urzal, e os javatuscos fizeram deles seu lar sagrado.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os javatuscos são ferozes e territoriais. Suas tribos são lideradas por senhores da guerra, e seus geomantes invocam a terra. Reverenciam a memória de Agamaggan e consideram o Urzal sagrado. Algumas de suas sacerdotisas se voltaram para artes mais sombrias, e alguns de seus guerreiros para senhores mais sombrios.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[A {link:razormane-quilboar}tribo Crinavalha{/link} saqueia as bordas de {link:durotar}Durotar{/link} e o norte dos {link:the-barrens}Sertões{/link}, e a tribo {link:bristleback-quilboar}Costagulha{/link} perturba as planícies de {link:mulgore}Mulgore{/link}. No sul, os javatuscos habitam as grandes tocas de espinhos do {link:razorfen-kraul}Urzal dos Tuscos{/link} e do {link:razorfen-downs}Urzal dos Mortos{/link}. Diz-se que no Urzal dos Mortos um culto chamado {link:death-s-head}Pontafatal{/link} se voltou para o {link:scourge}Flagelo{/link}, e que um lich agora habita entre eles.]=],
		},
	},
})

Translate("ptBR", "centaurs", {
	title = "Centauros",
	aliases = { "centauro" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os centauros são um povo cruel e belicoso de {link:kalimdor}Kalimdor{/link}. Têm a parte de cima do corpo de um homem e o corpo de um cavalo, e são saqueadores terríveis que cavalgam em bandos rápidos e impiedosos. Por gerações têm sido os maiores inimigos dos {link:tauren}taurens{/link}.]=],
		},
		{
			title = "Origens",
			text = [=[Diz-se que os centauros descendem da união de Zaetar, um filho do semideus {link:cenarius}Cenarius{/link}, com Theradras, uma princesa da terra elemental. Seus primeiros filhos eram cruéis além de toda medida e, num acesso de ciúme, mataram o próprio pai. Theradras sepultou Zaetar nas cavernas de {red:maraudon}Maraudon{/red}, onde se diz que seu espírito ainda permanece.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os centauros vivem como nômades e saqueadores. Sustentam que os fortes devem tomar dos fracos o que querem. Seus khans lideram as tribos, e as tribos guerreiam entre si quando não têm outros inimigos. São cavaleiros e arqueiros habilidosos, e mostram pouca misericórdia.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[A {link:kolkar-centaurs}tribo Kolkar{/link} percorre os {link:the-barrens}Sertões{/link}, e seus saqueadores atacam os postos avançados dos orcs ali. Os Galath cavalgam por {link:thousand-needles}Mil Agulhas{/link}. Na {link:desolace}Desolação{/link}, os Magram e os Gelkis travam uma longa rixa, e ambos reivindicam o favor de Theradras. Os Maraudinos guardam a entrada da própria Maraudon. Embora {link:cairne-bloodhoof}Cairne{/link} tenha expulsado os centauros de {link:mulgore}Mulgore{/link}, eles não esqueceram os taurens.]=],
		},
	},
})

Translate("ptBR", "furbolgs", {
	title = "Pelursos",
	aliases = { "pelurso" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os pelursos são um povo parecido com ursos das florestas do norte de {link:kalimdor}Kalimdor{/link}. Foram por muito tempo um povo manso e pacífico, amigo dos {link:night-elves}elfos noturnos{/link} e dos druidas. Nos últimos anos, uma doença do espírito caiu sobre a maioria de suas tribos, e muitos pelursos se tornaram selvagens e hostis.]=],
		},
		{
			title = "Origens",
			text = [=[Os pelursos vivem nas florestas de {link:kalimdor}Kalimdor{/link} desde tempos antigos. Já foram contados entre os aliados dos {link:night-elves}kaldorei{/link}. Nenhuma crônica registra seu início com mais detalhes.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os pelursos vivem em tribos, em tocas e aldeias escondidas no fundo dos bosques. Seus xamãs são sábios nos caminhos da floresta. A maioria se contentava em viver em silêncio e comerciar em paz com os vizinhos.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[A mácula demoníaca deixada nas florestas desde a {link:third-war}Terceira Guerra{/link} enlouqueceu muitas tribos. Os {link:thistlefur-village}Pelocardo{/link} e os Foulweald do {link:ashenvale}Vale Gris{/link}, os {link:deadwood-furbolgs}Lenha Morta{/link} da {link:felwood}Selva Maleva{/link}, os {link:blackwood-furbolgs}Bosqueneros{/link} da {link:darkshore}Costa Negra{/link}, os {link:gnarlpine-furbolgs}Masca-pinho{/link} de {link:teldrassil}Teldrassil{/link} e os {link:winterfall-furbolgs}Invernosos{/link} de {link:winterspring}Hibérnia{/link} voltaram-se contra seus antigos amigos. Só os {link:timbermaw-furbolgs}Presamatos{/link} resistiram à corrupção. Guardam os desfiladeiros do {link:timbermaw-hold}Domínio dos Presamatos{/link} e não confiam em nenhum forasteiro até que ele prove o seu valor.]=],
		},
	},
})

Translate("ptBR", "harpies", {
	title = "Harpias",
	aliases = { "harpia" },
	sections = {
		{
			title = "Resumo",
			text = [=[As harpias são criaturas aladas de {link:kalimdor}Kalimdor{/link}, com corpo de mulher e asas e garras de ave. São cruéis, astutas e ferozes, e caçam viajantes a partir de seus ninhos nos lugares altos.]=],
		},
		{
			title = "Origens",
			text = [=[As origens das harpias não estão registradas em nenhuma crônica conhecida por este registro.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[As harpias vivem em bandos governados por matriarcas. Fazem ninho em penhascos e serras e mergulham sobre tudo o que é mais fraco que elas. Gostam de coisas brilhantes roubadas e da carne dos que capturam. Suas bruxas comandam magia sombria.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[As {link:windfury-harpies}harpias Ventofúria{/link} fazem ninho nas serras de {link:mulgore}Mulgore{/link}, para grande aborrecimento dos taurens. As Witchwing se empoleiram nos {link:the-barrens}Sertões{/link}, as Bloodfury na {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link} e as Northspring em {link:feralas}Feralas{/link}. As estradas de {link:kalimdor}Kalimdor{/link} não são seguras sob seus ninhos.]=],
		},
	},
})

Translate("ptBR", "troggs", {
	title = "Troggs",
	aliases = { "trogg" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os troggs são criaturas brutas de pele de pedra que vivem nas profundezas da terra. São fortes, estúpidos e infinitamente agressivos. Por eras ficaram escondidos nas profundezas. Agora subiram à superfície, e trouxeram a ruína com eles.]=],
		},
		{
			title = "Origens",
			text = [=[Os registros de {link:uldaman}Uldaman{/link} contam que os troggs foram feitos pelos Titãs, como os terranos. Foram uma criação falha, e os Titãs os lacraram nas câmaras profundas do mundo. A {link:explorers-league}Liga dos Exploradores{/link} acredita que os anões perturbaram essas câmaras ao escavar em Uldaman, e que desde então os troggs vêm se espalhando.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os troggs vivem em tribos lideradas pelos mais fortes entre eles. Seus xamãs empunham uma magia rústica da terra. Pouco se importam com qualquer coisa além de lutar e comer.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os troggs se ergueram sob {link:gnomeregan}Gnomeregan{/link} e expulsaram os gnomos de sua cidade. Combatem os anões em {link:dun-morogh}Dun Morogh{/link} e em {link:loch-modan}Loch Modan{/link}, e enxameiam por {link:uldaman}Uldaman{/link} e pelos {link:badlands}Ermos{/link}. Onde quer que os anões cavem fundo, temem encontrar mais deles.]=],
		},
	},
})

Translate("ptBR", "ogres", {
	title = "Ogros",
	aliases = { "ogro" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os ogros são brutos enormes e de pouca inteligência, de grande força. Alguns têm duas cabeças, e uns poucos são feiticeiros astutos. A maioria veio a {link:azeroth}Azeroth{/link} com os orcs, de Draenor, e muitos clãs habitam agora os lugares selvagens dos dois continentes.]=],
		},
		{
			title = "Origens",
			text = [=[Os ogros serviram à {link:horde}Horda{/link} {link:orcs}orc{/link} na {link:second-war}Segunda Guerra{/link}. O bruxo {link:gul-dan}Gul'dan{/link} deu a alguns deles o dom da feitiçaria, e esses ogros magos se tornaram temidos por todos os {link:eastern-kingdoms}Reinos do Leste{/link}. O maior deles, Cho'gall, liderava o clã {link:twilight-s-hammer}Martelo do Crepúsculo{/link}. Depois da derrota da Horda, os clãs de ogros se dispersaram pelas colinas e montanhas.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os ogros são belicosos e gananciosos. Respeitam apenas a força e lutam entre si pela liderança. Seus chefes governam pelo porrete, e seus magos pelo medo.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Clãs de ogros ocupam as colinas de {link:redridge-mountains}Cristarrubra{/link}, da {link:stranglethorn-vale}Selva do Espinhaço{/link}, de {link:alterac-mountains}Alterac{/link} e do {link:arathi-highlands}Planalto Arathi{/link}. Em {link:kalimdor}Kalimdor{/link}, os Gordunni assombram {link:feralas}Feralas{/link}, e os Gordok governam as ruínas de {red:dire-maul}Gládio Cruel{/red}. No {link:dustwallow-marsh}Pântano Vadeoso{/link}, o clã Pedramalho decaiu de sua antiga força, e alguns de seus ogros vivem agora ao lado dos orcs.]=],
		},
	},
})

Translate("ptBR", "naga", {
	title = "Nagas",
	aliases = { "naga" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os nagas são criaturas serpentinas dos mares profundos. Foram outrora elfos noturnos da casta dos Bem-nascidos. Agora têm caudas escamosas e rostos cruéis, e voltaram das profundezas para perturbar as costas do mundo.]=],
		},
		{
			title = "Origens",
			text = [=[Quando o {link:well-of-eternity}Poço da Eternidade{/link} foi destruído na {link:great-sundering}Grande Cisão{/link}, o palácio da {link:queen-azshara}Rainha Azshara{/link} foi engolido pelo mar com toda a sua corte. Algo nas profundezas os salvou, e os transformou. Os Bem-nascidos afogados se tornaram os nagas. Por dez mil anos viveram escondidos sob as ondas. No tempo da {link:third-war}Terceira Guerra{/link} ergueram-se de novo, e serviram a {link:illidan-stormrage}Illidan Stormrage{/link} por um tempo.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os nagas são orgulhosos, amargos e ambiciosos. Suas sereias são feiticeiras poderosas que comandam as águas e as tempestades. Seus mirmidões são guerreiros temíveis. Diz-se que ainda honram {link:azshara}Azshara{/link} nas profundezas.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os nagas reivindicaram trechos de costa em {link:azshara}Azshara{/link}, na {link:darkshore}Costa Negra{/link}, no {link:ashenvale}Vale Gris{/link} e na {link:desolace}Desolação{/link}. Assombram o templo inundado das {link:blackfathom-deeps}Profundezas Negras{/link}. O que buscam nas costas de {link:kalimdor}Kalimdor{/link}, os elfos noturnos não sabem.]=],
		},
	},
})

Translate("ptBR", "satyrs", {
	title = "Sátiros",
	aliases = { "sátiro" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os sátiros são demônios da floresta, chifrudos e com pernas de bode. Foram outrora elfos noturnos Bem-nascidos que se venderam à {link:burning-legion}Legião Ardente{/link}. Agora assombram os bosques corrompidos do norte de {link:kalimdor}Kalimdor{/link}, espalhando a mácula da {link:fel-magic}magia vil{/link} por onde passam.]=],
		},
		{
			title = "Origens",
			text = [=[Na {link:war-of-the-ancients}Guerra dos Antigos{/link}, Lorde Xavius, conselheiro da {link:queen-azshara}Rainha Azshara{/link}, foi o primeiro dos Bem-nascidos a servir aos demônios. Depois de sua derrota, o senhor da Legião o refez como o primeiro sátiro. Xavius, por sua vez, levou muitos dos Bem-nascidos ao mesmo destino. Os sátiros lutaram pela Legião durante toda a guerra, e muitos sobreviveram à {link:great-sundering}Cisão{/link}.]=],
		},
		{
			title = "Natureza e Costumes",
			text = [=[Os sátiros são cruéis, traiçoeiros e famintos de poder. Servem aos demônios, esteja a Legião perto ou longe. Sua magia é vil, e corrompem a terra onde habitam. Suas tribos vivem em bosques sombrios nas florestas que devastam.]=],
		},
		{
			title = "Nos Dias Atuais",
			text = [=[Os sátiros se espalharam pelas florestas desde a {link:third-war}Terceira Guerra{/link}. Infestam a {link:felwood}Selva Maleva{/link} e o {link:ashenvale}Vale Gris{/link}, onde {link:satyrnaar}Satyrnaar{/link} é seu baluarte, e espreitam nas ruínas de {link:azshara}Azshara{/link} e nas profundezas de {red:dire-maul}Gládio Cruel{/red}. As {link:sentinels}Sentinelas{/link} os caçam sem piedade.]=],
		},
	},
})
